    P.box('role_V', 450, 292, 204, 58, { cls: rest ? 'ghost' : on(['VR']), title: 'View', sub: vSub });
    var link = function (id, to) { P.arrow('ar_' + id, 'st_' + id + ':r', to, { cls: id === s.cur ? 'hot' : at(id) ? (id === s.end ? 'bad' : 'good') : done ? 'mut dash' : 'mut' }); };
