      if (s.inst) rows.push({ cells: ['moment', 'Instant', { v: '2023-12-31T15:30:00Z', cls: 'good' }] });
      if (s.there) rows.push({ cells: ['there', 'ZonedDateTime', { v: z.zdt, cls: 'hot' }] });
